(function() {
    'use strict';

    class MesaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Mesa';
            this.version = '1.1.0';
            this.CORRECT = {
                landedPrice: 2060,
                effectivePrice: 2165,
                batnaRevenue: 22.8,
                batnaEbitda: 10.8,
                metalicosReservation: 2080,
                cbgReservation: 2234,
                zopaMidpoint: 2157
            };
            this.ROUND_NAME_KEYS = ['round1_name', 'round2_name', 'round3_name', 'round4_name'];
            this.BRIEFING_KEYS = ['round1_briefing', 'round2_briefing', 'round3_briefing', 'round4_briefing'];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    scoreHistory: [],
                    roundFeedback: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    landedPrice: 2000,
                    effectivePrice: 2100,
                    batnaRevenue: 20,
                    batnaEbitda: 10,
                    metalicosReservation: 2100,
                    cbgReservation: 2200,
                    zopaMidpoint: 2150,
                    anchorPrice: 2240,
                    firstConcession: 2180,
                    volumeCondition: 15,
                    secondConcession: 2140,
                    finalPrice: 2180,
                    volumeCommitment: 15,
                    contractTerm: 2,
                    paymentTerms: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var lp = document.getElementById('landedPriceInput');
                if (lp) decisions.landedPrice = parseFloat(lp.value);
                var ep = document.getElementById('effectivePriceInput');
                if (ep) decisions.effectivePrice = parseFloat(ep.value);
                var br = document.getElementById('batnaRevenueInput');
                if (br) decisions.batnaRevenue = parseFloat(br.value);
                var be = document.getElementById('batnaEbitdaInput');
                if (be) decisions.batnaEbitda = parseFloat(be.value);

                if (!decisions.landedPrice || decisions.landedPrice < 1500 || decisions.landedPrice > 3000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('price_range_warning'), 'warning');
                    return false;
                }
                if (!decisions.effectivePrice || decisions.effectivePrice < 1500 || decisions.effectivePrice > 3000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('price_range_warning'), 'warning');
                    return false;
                }
            } else if (period === 2) {
                var mr = document.getElementById('metalicosReservationInput');
                if (mr) decisions.metalicosReservation = parseFloat(mr.value);
                var cr = document.getElementById('cbgReservationInput');
                if (cr) decisions.cbgReservation = parseFloat(cr.value);
                var zm = document.getElementById('zopaMidpointInput');
                if (zm) decisions.zopaMidpoint = parseFloat(zm.value);

                if (!decisions.metalicosReservation || decisions.metalicosReservation < 1500 || decisions.metalicosReservation > 3000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('reservation_warning'), 'warning');
                    return false;
                }
                if (!decisions.cbgReservation || decisions.cbgReservation < 1500 || decisions.cbgReservation > 3000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('reservation_warning'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                var ap = document.getElementById('anchorPriceInput');
                if (ap) decisions.anchorPrice = parseFloat(ap.value);
                var fc = document.getElementById('firstConcessionInput');
                if (fc) decisions.firstConcession = parseFloat(fc.value);
                var vc = document.getElementById('volumeConditionInput');
                if (vc) decisions.volumeCondition = parseFloat(vc.value);
                var sc = document.getElementById('secondConcessionInput');
                if (sc) decisions.secondConcession = parseFloat(sc.value);

                if (!decisions.anchorPrice || decisions.anchorPrice < 1500 || decisions.anchorPrice > 3000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('price_range_warning'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                var fp = document.getElementById('finalPriceInput');
                if (fp) decisions.finalPrice = parseFloat(fp.value);
                var vcm = document.getElementById('volumeCommitmentInput');
                if (vcm) decisions.volumeCommitment = parseFloat(vcm.value);
                var ct = document.getElementById('contractTermInput');
                if (ct) decisions.contractTerm = parseInt(ct.value);
                var pt = document.getElementById('paymentTermsInput');
                if (pt) decisions.paymentTerms = parseInt(pt.value);

                if (!decisions.finalPrice || decisions.finalPrice < 1500 || decisions.finalPrice > 3000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('price_range_warning'), 'warning');
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var d = state.decisions;
            var roundScore = 0;
            var feedback = '';
            var C = this.CORRECT;

            if (period === 1) {
                var lpErr = Math.abs(d.landedPrice - C.landedPrice);
                var lpScore = Math.max(0, 8 - Math.floor(lpErr / 25));
                var epErr = Math.abs(d.effectivePrice - C.effectivePrice);
                var epScore = Math.max(0, 7 - Math.floor(epErr / 25));
                var brErr = Math.abs(d.batnaRevenue - C.batnaRevenue);
                var brScore = Math.max(0, 5 - Math.floor(brErr / 1));
                var beErr = Math.abs(d.batnaEbitda - C.batnaEbitda);
                var beScore = Math.max(0, 5 - Math.floor(beErr / 0.5));

                roundScore = lpScore + epScore + brScore + beScore;

                feedback = window.mySimulation.t('r1_feedback_landed') + ' COP ' + C.landedPrice.toLocaleString() + '/kg'
                    + '<br>' + window.mySimulation.t('r1_feedback_effective') + ' COP ' + C.effectivePrice.toLocaleString() + '/kg'
                    + '<br>' + window.mySimulation.t('r1_feedback_batna_rev') + ' COP ' + C.batnaRevenue + 'B'
                    + '<br>' + window.mySimulation.t('r1_feedback_batna_ebitda') + ' COP ' + C.batnaEbitda + 'B';

            } else if (period === 2) {
                var mrErr = Math.abs(d.metalicosReservation - C.metalicosReservation);
                var mrScore = Math.max(0, 8 - Math.floor(mrErr / 20));
                var crErr = Math.abs(d.cbgReservation - C.cbgReservation);
                var crScore = Math.max(0, 9 - Math.floor(crErr / 20));
                var zmErr = Math.abs(d.zopaMidpoint - C.zopaMidpoint);
                var zmScore = Math.max(0, 8 - Math.floor(zmErr / 15));

                roundScore = mrScore + crScore + zmScore;

                feedback = window.mySimulation.t('r2_feedback_metalicos_res') + ' COP ' + C.metalicosReservation.toLocaleString() + '/kg'
                    + '<br>' + window.mySimulation.t('r2_feedback_cbg_res') + ' COP ' + C.cbgReservation.toLocaleString() + '/kg'
                    + '<br>' + window.mySimulation.t('r2_feedback_zopa') + ' COP 2,080 \u2013 2,234/kg'
                    + '<br>' + window.mySimulation.t('r2_feedback_midpoint') + ' COP ' + C.zopaMidpoint.toLocaleString() + '/kg';

            } else if (period === 3) {
                var anchorScore = d.anchorPrice >= 2200 ? 6 : (d.anchorPrice >= 2100 ? 3 : 1);
                var fc1Score = 0;
                if (d.firstConcession < d.anchorPrice && d.firstConcession >= 2080 && d.firstConcession <= 2234) {
                    fc1Score = 7;
                } else if (d.firstConcession < d.anchorPrice && d.firstConcession >= 2000) {
                    fc1Score = 4;
                } else if (d.firstConcession < d.anchorPrice) {
                    fc1Score = 2;
                }
                var volScore = d.volumeCondition > 0 ? 5 : 0;
                var fc2Score = 0;
                if (d.secondConcession < d.firstConcession && d.secondConcession >= 2080) {
                    fc2Score = 4;
                } else if (d.secondConcession < d.firstConcession && d.secondConcession >= 2000) {
                    fc2Score = 2;
                }
                var firstDrop = d.anchorPrice - d.firstConcession;
                var secondDrop = d.firstConcession - d.secondConcession;
                var decreasingScore = (secondDrop < firstDrop && secondDrop > 0) ? 3 : (secondDrop > 0 ? 1 : 0);

                roundScore = anchorScore + fc1Score + volScore + fc2Score + decreasingScore;

                feedback = window.mySimulation.t('r3_feedback_anchor') + ' ' + (anchorScore >= 5 ? '\u2705' : '\u26a0\ufe0f')
                    + '<br>' + window.mySimulation.t('r3_feedback_concessions') + ' ' + (fc1Score >= 5 ? '\u2705' : '\u26a0\ufe0f')
                    + '<br>' + window.mySimulation.t('r3_feedback_conditions') + ' ' + (volScore >= 4 ? '\u2705' : '\u26a0\ufe0f')
                    + '<br>' + window.mySimulation.t('r3_feedback_decreasing') + ' ' + (decreasingScore >= 2 ? '\u2705' : '\u26a0\ufe0f');

            } else if (period === 4) {
                var priceScore = 0;
                if (d.finalPrice >= 2080 && d.finalPrice <= 2234) {
                    priceScore = d.finalPrice >= 2157 ? 10 : 7;
                } else if (d.finalPrice >= 2000 && d.finalPrice <= 2300) {
                    priceScore = 4;
                }
                var volFinalScore = d.volumeCommitment > 10 ? 5 : (d.volumeCommitment > 0 ? 3 : 0);
                var termScore = d.contractTerm >= 2 ? 5 : (d.contractTerm >= 1 ? 2 : 0);
                var payScore = d.paymentTerms <= 45 ? 5 : (d.paymentTerms <= 60 ? 4 : 2);

                roundScore = priceScore + volFinalScore + termScore + payScore;

                var inZopa = (d.finalPrice >= 2080 && d.finalPrice <= 2234);
                feedback = window.mySimulation.t('r4_feedback_price') + ' ' + (inZopa ? '\u2705' : '\u274c')
                    + '<br>' + window.mySimulation.t('r4_feedback_volume') + ' ' + (d.volumeCommitment > 0 ? '\u2705' : '\u26a0\ufe0f')
                    + '<br>' + window.mySimulation.t('r4_feedback_term') + ' ' + (d.contractTerm >= 2 ? '\u2705' : '\u26a0\ufe0f')
                    + '<br>' + window.mySimulation.t('r4_feedback_payment') + ' ' + (d.paymentTerms <= 60 ? '\u2705' : '\u26a0\ufe0f');
            }

            state.domainState.score += roundScore;
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.roundFeedback = feedback;

            // v1.1.0 (consistency hardening, NOT a bugfix): this sim already persists
            // domainState.score (0-100), which the grading layer resolves via the
            // 'score' candidate. We ALSO expose it on the preferred path
            // (domainState.performance.overallScore, checked first by
            // results_utils.php::express_resolveDomainScore) so 412 matches the rest of
            // the Express catalog and is robust to any scoring_field configuration.
            var _ov = Math.max(0, Math.min(100, state.domainState.score));
            state.domainState.performance = {
                overallScore: _ov,
                grade: (_ov >= 85 ? 'Master Negotiator' : _ov >= 70 ? 'Excellent' : _ov >= 50 ? 'Good' : 'Beginner')
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                var fbEl = document.getElementById('feedbackText');
                if (fbEl) fbEl.innerHTML = feedback;
                var fbCard = document.getElementById('feedbackCard');
                if (fbCard) fbCard.style.display = 'block';
            }, 500);

            return {
                period: period,
                roundScore: roundScore,
                totalScore: state.domainState.score,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score', function(v) { return v + ' / 100'; });
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            backgroundColor: ['rgba(52,152,219,0.7)', 'rgba(46,204,113,0.7)', 'rgba(155,89,182,0.7)', 'rgba(230,126,34,0.7)'],
                            borderColor: ['#3498db', '#2ecc71', '#9b59b6', '#e67e22'],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score by Round' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 25 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var roundLabels = ['BATNA', 'ZOPA', 'Strategy', 'Negotiation'];
            var labels = state.domainState.scoreHistory.map(function(_, i) { return roundLabels[i] || ('R' + (i + 1)); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = history.reduce(function(s, r) { return s + (r.results ? r.results.roundScore : 0); }, 0);
            var performance = 'Beginner';
            if (total >= 50) performance = 'Good';
            if (total >= 70) performance = 'Excellent';
            if (total >= 85) performance = 'Master Negotiator';

            var insights = [];
            if (total >= 85) {
                insights.push('Outstanding negotiation preparation with rigorous analytical and strategic thinking.');
            } else if (total >= 70) {
                insights.push('Solid grasp of BATNA and ZOPA fundamentals. Refine your concession strategy for even better results.');
            } else if (total >= 50) {
                insights.push('Good foundation. Review the TCO analysis methodology and practice building conditional concession sequences.');
            } else {
                insights.push('Focus on the fundamentals: always calculate the full TCO before accepting competitor price claims, and never concede without conditions.');
            }

            return {
                totalScore: total,
                maxScore: 100,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.roundScore < 15) {
                return window.mySimulation.t('hint_r1');
            }
            if (state.currentPeriod === 2 && results.roundScore < 15) {
                return window.mySimulation.t('hint_r2');
            }
            if (state.currentPeriod === 3 && results.roundScore < 15) {
                return window.mySimulation.t('hint_r3');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score', formatter: function(v) { return v + ' / 25'; } },
                { key: 'results.totalScore', label: 'Cumulative', i18nKey: 'col_cumulative', formatter: function(v) { return v + ' / 100'; } }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                      `La Mesa`,
                    subtitle:                   `BATNA, ZOPA and Reservation Price: Negotiation Preparation`,
                    round_label:                `Round`,
                    period_of:                  `of`,
                    score_label:                `Score`,
                    round_name_label:           `Current Phase`,
                    current_price_label:        `Current Price`,
                    cbg_demand_label:           `CBG Demand`,
                    decisions_heading:          `Your Analysis`,
                    submit_btn:                 `Submit Round`,
                    undo_btn:                   `Undo Last Round`,
                    briefing_title:             `Briefing`,
                    feedback_title:             `Feedback`,
                    round1_name:                `Calculate BATNAs`,
                    round2_name:                `Define ZOPA`,
                    round3_name:                `Negotiation Strategy`,
                    round4_name:                `The Negotiation`,
                    landed_price_label:         `Real landed price of Chinese steel (COP/kg)`,
                    landed_price_ph:            `e.g. 2060`,
                    effective_price_label:      `Total effective price with hidden costs (COP/kg)`,
                    effective_price_ph:         `e.g. 2165`,
                    batna_revenue_label:        `BATNA revenue for Metalicos (COP billions)`,
                    batna_revenue_ph:           `e.g. 22.8`,
                    batna_ebitda_label:         `BATNA EBITDA for Metalicos (COP billions)`,
                    batna_ebitda_ph:            `e.g. 10.8`,
                    metalicos_reservation_label: `Reservation price of Metalicos (COP/kg)`,
                    metalicos_res_ph:           `e.g. 2080`,
                    cbg_reservation_label:      `Reservation price of CBG (COP/kg)`,
                    cbg_res_ph:                 `e.g. 2234`,
                    zopa_midpoint_label:        `ZOPA midpoint (COP/kg)`,
                    zopa_mid_ph:                `e.g. 2157`,
                    anchor_price_label:         `Opening anchor price (COP/kg)`,
                    anchor_ph:                  `e.g. 2240`,
                    first_concession_label:     `First concession price (COP/kg)`,
                    first_conc_ph:              `e.g. 2180`,
                    volume_condition_label:     `Volume increase condition (%)`,
                    vol_cond_ph:                `e.g. 15`,
                    second_concession_label:    `Second concession price (COP/kg)`,
                    second_conc_ph:             `e.g. 2140`,
                    final_price_label:          `Final agreed price (COP/kg)`,
                    final_price_ph:             `e.g. 2180`,
                    volume_commitment_label:    `Volume change (%)`,
                    vol_commit_ph:              `e.g. 15`,
                    contract_term_label:        `Contract term (years)`,
                    contract_ph:                `e.g. 2`,
                    payment_terms_label:        `Payment terms (days)`,
                    payment_ph:                 `e.g. 60`,
                    price_range_warning:        `Price must be between COP 1,500 and COP 3,000 per kg`,
                    reservation_warning:        `Reservation price must be between COP 1,500 and COP 3,000 per kg`,
                    round1_briefing:            `<strong>Metalicos del Valle S.A.S.</strong> (Cali, Colombia) manufactures structural steel products sold at <strong>COP 2,240/kg</strong>. Their largest client, <strong>Constructora Bogota Grande (CBG)</strong>, represents 31% of revenue (COP 26.35B/year, 11.76M kg/year) and is demanding a <strong>12% price reduction</strong>, citing Chinese steel available at COP 1,820/kg.<br><br>Your task: Calculate the <strong>REAL landed cost</strong> of Chinese steel in Bogota and the <strong>total effective price</strong> including all hidden costs. Also estimate the BATNA of Metalicos (revenue and EBITDA if CBG leaves).<br><br><strong>Chinese steel cost data:</strong><br>\u2022 FOB China: USD 520/ton (at COP 3,200/USD)<br>\u2022 Maritime freight Shanghai \u2192 Buenaventura: USD 42/ton<br>\u2022 Import tariff: 8% on CIF value<br>\u2022 Insurance and customs: COP 28/kg<br>\u2022 Transport Buenaventura \u2192 Bogota: COP 90/kg<br><br><strong>Hidden cost data:</strong><br>\u2022 Chinese lead time: 14 weeks (vs. 3 weeks for Metalicos)<br>\u2022 Additional inventory needed: 11 weeks of coverage<br>\u2022 CBG volume: 11.76M kg/year; cost of debt: 16% EA<br>\u2022 Quality rejection risk: 3-5% (est. COP 380M/year)<br>\u2022 Supply delay penalty: COP 280M/week (15% probability/year)<br><br><strong>BATNA data for Metalicos:</strong><br>\u2022 3 mid-size builders: COP 8.4B each, 2-4% lower prices, 6-month ramp-up<br>\u2022 Export to Ecuador/Peru: 96,000 ton at COP 2,180/kg, 4-month ramp`,
